function loadDocs(key){
  var doc=DOCS[key];if(!doc){$('content').innerHTML='<div class="empty-hint">文档不存在</div>';return}
  var h='<div class="card"><h3>'+esc(doc.title)+'</h3><p style="font-size:.75rem;color:var(--muted)">Base path: <code>'+esc(doc.base)+'</code></p></div>';
  /* Schema */
  h+='<div class="card"><h3>数据结构</h3><table class="doc-param-table"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody>';
  doc.schema.forEach(function(s){h+='<tr><td class="pname">'+esc(s[0])+'</td><td class="ptype">'+esc(s[1])+'</td><td>'+esc(s[2])+'</td></tr>'});
  h+='</tbody></table></div>';
  /* Endpoints */
  doc.endpoints.forEach(function(ep){
    h+='<div class="card"><div class="doc-endpoint"><span class="doc-method '+ep.m.toLowerCase()+'">'+ep.m+'</span><span>'+esc(doc.base+ep.p)+'</span></div>';
    h+='<p style="font-size:.75rem;margin-bottom:.4rem">'+esc(ep.d)+'</p>';
    if(ep.qp&&ep.qp.length){
      h+='<div class="doc-section"><h4>Query 参数</h4><table class="doc-param-table"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody>';
      ep.qp.forEach(function(p){h+='<tr><td class="pname">'+esc(p[0])+'</td><td class="ptype">'+esc(p[1])+'</td><td>'+esc(p[2])+'</td></tr>'});
      h+='</tbody></table></div>';
    }
    if(ep.body&&ep.body.length){
      h+='<div class="doc-section"><h4>Body 参数 (JSON)</h4><table class="doc-param-table"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody>';
      ep.body.forEach(function(p){h+='<tr><td class="pname">'+esc(p[0])+'</td><td class="ptype">'+esc(p[1])+'</td><td>'+esc(p[2])+'</td></tr>'});
      h+='</tbody></table></div>';
    }
    h+='<div class="doc-section"><h4>响应</h4><code style="font-size:.72rem">'+esc(ep.res)+'</code></div></div>';
  });
  $('content').innerHTML=h;
}

