// ── HashRouter Transform Plugin ────────────────────────────────────────────
// Compiled sites are served from arbitrary base paths (Alibaba platform, file://,
// iframes). BrowserRouter relies on pathname and breaks. HashRouter uses the
// URL hash fragment and works everywhere.
function __hashRouterPlugin() {
  return {
    name: 'phoenix-hash-router',
    apply: 'build',
    transform(code, id) {
      if (id.indexOf('node_modules') >= 0) return null
      if (!/\\.(tsx?|jsx?|mjs)$/.test(id)) return null
      if (code.indexOf('BrowserRouter') < 0) return null
      var out = code
        .replace(/BrowserRouter/g, 'HashRouter')
      if (out !== code) {
        console.log('[hash-router] replaced BrowserRouter → HashRouter in ' + id)
        return { code: out, map: null }
      }
      return null
    },
  }
}

// ── Inline Plugin ──────────────────────────────────────────────────────────
